// 以下代码用于说明接口，完整定义以参赛包 include/ 中的头文件为准

// Status 类（简化版）
class Status {
 public:
  static Status OK();
  static Status NotFound(const std::string& msg = ""); // key不存在
  static Status IOError(const std::string& msg = ""); // 其他错误
  bool IsOk() const;
  bool IsNotFound() const;
  std::string ToString() const;
};

// 参赛者必须继承并实现以下接口
class KVEngine {
 public:
  // 目录不存在时创建引擎，目录存在时恢复
  // 失败时将输出指针置空。成功创建的实例由调用方销毁，调用方在销毁前停止前台调用，引擎负责停止并回收后台线程
  // data_dir: 数据目录（引擎运行文件存放于此，Checkpoint 可输出到独立目录）
  // mem_limit_bytes: 引擎内存预算（字节），引擎须主动控制内存，必要时提前落盘并回收索引缓存
  static Status Open(const std::string& data_dir,
                     uint64_t mem_limit_bytes,
                     KVEngine** engine);

  // 写入 key-value；若 key 已存在则覆盖
  virtual Status Put(const std::string& key, const std::string& value) = 0;

  // 读取 key 对应的 最新value；key 不存在时返回 NotFound
  virtual Status Get(const std::string& key, std::string* value) = 0;

  // 删除 key；key 不存在时返回 OK（幂等）
  virtual Status Delete(const std::string& key) = 0;

  // 可选加分接口：创建可独立打开的一致性副本
  // checkpoint_dir: 不存在的目标目录，须位于原数据目录之外
  // 未实现此接口不影响基础评审
  virtual Status CreateCheckpoint(const std::string& checkpoint_dir) {
    return Status::IOError("Checkpoint is not supported");
  }

  virtual ~KVEngine() = default;
};
